// A shared visual activity: rules and moves are local, never generated by a model.
(function () {
  'use strict';
  const lines=[[0,1,2],[3,4,5],[6,7,8],[0,3,6],[1,4,7],[2,5,8],[0,4,8],[2,4,6]];
  const positions={
    en:['top left','top middle','top right','middle left','center','middle right','bottom left','bottom middle','bottom right'],
    zh:['左上角','上方中间','右上角','左边中间','正中间','右边中间','左下角','下方中间','右下角'],
  };
  function result(board) {
    const line=lines.find(cells=>board[cells[0]] && cells.every(i=>board[i]===board[cells[0]]));
    return line?{winner:board[line[0]],line:[...line]}:{winner:board.every(Boolean)?'draw':null,line:[]};
  }
  function create() {return {board:Array(9).fill(null),turn:'X',winner:null,line:[],lastMove:null};}
  function place(game,index,mark) {
    if(!game || game.winner || game.turn!==mark || !Number.isInteger(index) || index<0 || index>8 || game.board[index])return game;
    const board=[...game.board];board[index]=mark;
    const outcome=result(board);
    return {board,turn:outcome.winner?null:mark==='X'?'O':'X',...outcome,lastMove:{index,mark}};
  }
  function chooseMove(game) {
    if(!game || game.winner || game.turn!=='O')return null;
    const empty=game.board.map((mark,i)=>mark===null?i:null).filter(i=>i!==null);
    for(const mark of ['O','X'])for(const i of empty){const board=[...game.board];board[i]=mark;if(result(board).winner===mark)return i;}
    // A friendly, predictable opponent: win/block first, then a preferred square.
    return [4,0,8,2,6,1,3,5,7].find(i=>game.board[i]===null) ?? null;
  }
  function miniMove(game) {const index=chooseMove(game);return index===null?game:place(game,index,'O');}
  function wantsGame(text) {return typeof text==='string' && /\btic[\s-]*(?:tac|tik|tack)[\s-]*toe\b|\bnoughts?\s+and\s+crosses\b|井字棋|圈叉棋/i.test(text);}
  function wantsReplay(text) {return /\b(?:play again|another round|new game|restart|new round)\b|\btic[\s-]*(?:tac|tik|tack)[\s-]*toe\b.*\bagain\b|再来一局|再玩一次|再玩.*(?:井字棋|圈叉棋)|重新开始|新的一局/i.test(text || '');}
  function wantsExit(text) {return /\b(?:back to (?:mini|chat)|close (?:the )?(?:board|game)|(?:let['’]?s|let us|can we) (?:just )?(?:chat|talk)|stop (?:playing )?tic[\s-]*(?:tac|tik|tack)[\s-]*toe)\b|返回聊天|回到聊天|关闭棋盘|不玩棋了|我想聊天/i.test(text || '');}
  function parsePosition(value) {
    if(typeof value!=='string')return null;
    let text=value.toLowerCase().replace(/[.,!?，。！？-]/g,' ').replace(/\s+/g,' ').trim();
    if(/\b(?:not|don['’]?t|do not)\b|不要|不是|别放/.test(text))return null;
    const found=new Set();
    const numerals={one:1,two:2,three:3,一:1,二:2,三:3};
    const number=word=>numerals[word] || Number(word);
    text=text.replace(/row\s*(one|two|three|[1-3])\s*(?:and\s*)?column\s*(one|two|three|[1-3])|第?([一二三1-3])行第?([一二三1-3])列/g,(_,r,c,zr,zc)=>{
      found.add((number(r || zr)-1)*3+number(c || zc)-1);return ' ';
    });
    const aliases=[
      [0,/\b(?:top|upper)\s*(?:left)\b|左上(?:角|方)?/g],
      [1,/\b(?:top|upper)\s*(?:middle|center|centre)\b|(?:上方|上面|上排|顶部|上)中间|上中/g],
      [2,/\b(?:top|upper)\s*right\b|右上(?:角|方)?/g],
      [3,/\b(?:middle|center|centre)\s*left\b|\bleft\s*(?:middle|center|centre)\b|左边中间|中间左边|左中/g],
      [5,/\b(?:middle|center|centre)\s*right\b|\bright\s*(?:middle|center|centre)\b|右边中间|中间右边|右中/g],
      [6,/\b(?:bottom|lower)\s*left\b|左下(?:角|方)?/g],
      [7,/\b(?:bottom|lower)\s*(?:middle|center|centre)\b|(?:下方|下面|下排|底部|下)中间|下中/g],
      [8,/\b(?:bottom|lower)\s*right\b|右下(?:角|方)?/g],
      [4,/\b(?:center|centre|middle)\b|正中间|中间|中央|中心/g],
    ];
    for(const [index,pattern] of aliases)text=text.replace(pattern,()=>{found.add(index);return ' ';});
    const words=['one','two','three','four','five','six','seven','eight','nine'];
    const match=text.match(/^(?:(?:please\s+)?(?:choose|pick|square|number|cell)\s+)?(one|two|three|four|five|six|seven|eight|nine|[1-9])(?:\s+please)?$/);
    if(match)found.add(/^\d$/.test(match[1])?Number(match[1])-1:words.indexOf(match[1]));
    const chinese=text.match(/^第?([一二三四五六七八九1-9])(?:个)?格(?:子)?$/);
    if(chinese)found.add(/[1-9]/.test(chinese[1])?Number(chinese[1])-1:'一二三四五六七八九'.indexOf(chinese[1]));
    return found.size===1?[...found][0]:null;
  }
  function checkpoint(game) {
    return game?'Visual tic-tac-toe board is authoritative: '+JSON.stringify(game)+
      '. Child is X; Mini is O. The browser alone places both marks and determines wins. Never invent, choose, announce a square placement, or claim a winner from speech. Briefly acknowledge the child and refer to the visible board. The child can tap an empty square or say its position. Do not continue a previous story or riddle while this board is active.':'';
  }
  function init(options) {
    const $=id=>document.getElementById(id),shell=document.querySelector('.shell');
    const panel=$('boardActivity'),board=$('ticBoard'),status=$('boardStatus');
    const cells=Array.from(board.querySelectorAll('button'));
    let game=null,timer=null,round=0,spokenLanguage='en';
    const lang=()=>options.getLanguage()==='zh'?'zh':options.getLanguage()==='auto'?spokenLanguage:'en';
    function statusText() {
      const zh=lang()==='zh';
      if(game.winner==='X')return zh?'你连成三个啦！真棒！':'Three in a row—you did it!';
      if(game.winner==='O')return zh?'Mini 连成三个啦。再来一局吧！':'Mini has three in a row. Shall we try again?';
      if(game.winner==='draw')return zh?'平局！棋盘满啦。':'A draw! We filled the board together.';
      return game.turn==='O'?(zh?'轮到 Mini 啦……':'Mini’s turn…'):(zh?'轮到你啦！选一个空格。':'Your turn! Choose an empty square.');
    }
    function render(message) {
      if(!game)return;
      const zh=lang()==='zh';
      $('boardTitle').textContent=zh?'一起玩井字棋':'Tic-tac-toe together';
      $('boardHelp').textContent=zh?'你是 ×，Mini 是 ○。点空格；语音聊天时也可以说“左上角”或“中间”。':'You are ×. Mini is ○. Tap an empty square—or say “top left” or “center” during live chat.';
      $('boardExit').textContent=zh?'回到 Mini':'Back to Mini';
      $('boardReplay').textContent=zh?'再来一局':'New round';
      $('boardVoiceNote').textContent=options.getSession()?.mode==='realtime'
        ? (zh?'语音仍使用当前付费会话；棋盘和落子在本地运行。':'Voice uses your current paid session. The board and moves run locally.')
        : (zh?'免费本地游戏 · 不使用麦克风或摄像头':'Free local game · no microphone or camera');
      status.textContent=message || statusText();
      board.setAttribute('aria-label',zh?'三行三列井字棋，你是叉':'Three-by-three tic-tac-toe board. You are X.');
      for(const [i,cell] of cells.entries()) {
        const mark=game.board[i];
        cell.classList.toggle('mark-x',mark==='X');cell.classList.toggle('mark-o',mark==='O');
        cell.classList.toggle('winning',game.line.includes(i));
        cell.classList.toggle('last-move',game.lastMove?.index===i);
        cell.textContent=mark?'':String(i+1);
        cell.disabled=Boolean(mark || game.winner || game.turn!=='X');
        cell.setAttribute('aria-label',positions[lang()][i]+', '+(mark || (zh?'空格':'empty'))+', '+(i+1));
      }
    }
    function changed() {render();options.onChange?.(game);}
    function open() {
      clearTimeout(timer);round+=1;game=create();
      options.onStart?.();
      shell.dataset.visualActivity='tictactoe';panel.classList.remove('hidden');
      $('boardPlayBtn').classList.add('hidden');$('localPlayBtn').classList.add('hidden');
      changed();
      $('kidLiveTag').textContent=options.getSession()?.mode==='realtime'?'● VOICE + BOARD':'✦ LOCAL PLAY';
      window.scrollTo({top:0,behavior:'auto'});
    }
    function close(notify=true) {
      clearTimeout(timer);round+=1;game=null;
      delete shell.dataset.visualActivity;panel.classList.add('hidden');
      $('boardPlayBtn').classList.toggle('hidden',Boolean(options.getSession()));
      $('localPlayBtn').classList.toggle('hidden',Boolean(options.getSession()));
      if(notify)options.onExit?.();
    }
    function move(index) {
      if(!game)return false;
      const next=place(game,index,'X');
      if(next===game) {
        const zh=lang()==='zh';
        render(game.winner?(zh?'这一局结束啦，可以再来一局。':'This round is finished. Try a new round.'):
          game.turn==='O'?(zh?'等 Mini 落子，再轮到你。':'Let Mini place a mark, then it is your turn.'):
          zh?'这个格子有棋子啦，选一个空格吧。':'That square is taken. Choose an empty square.');
        return false;
      }
      game=next;changed();
      if(game.winner){options.onResult?.(game.winner);return true;}
      const token=round;
      timer=setTimeout(()=>{
        if(!game || token!==round)return;
        game=miniMove(game);changed();
        if(game.winner)options.onResult?.(game.winner);
      },550);
      return true;
    }
    function handleTranscript(text,voiceRound=null) {
      if(typeof text!=='string')return false;
      if(options.getLanguage()==='auto') {
        if(/[\u3400-\u9fff]/.test(text))spokenLanguage='zh';
        else if(/[a-z]/i.test(text))spokenLanguage='en';
      }
      if(game && wantsExit(text)){close();return true;}
      if(wantsGame(text) && !/\b(?:not|don['’]?t|do not)\b|不要|不想/.test(text.toLowerCase())){if(!game || wantsReplay(text))open();return true;}
      if(!game)return false;
      if(wantsExit(text)){close();return true;}
      if(wantsReplay(text)){open();return true;}
      if(voiceRound!==null && voiceRound!==round)return true;
      const index=parsePosition(text);
      if(index!==null){move(index);return true;}
      if(/\b(?:top|bottom|middle|center|square|row|column)\b|左上|右上|左下|右下|中间|格子/.test(text.toLowerCase())) {
        render(lang()==='zh'?'请只选一个空格，或者直接点它。':'Choose one square, or tap it on the board.');return true;
      }
      return false;
    }
    for(const [index,cell] of cells.entries())cell.addEventListener('click',()=>move(index));
    $('boardReplay').addEventListener('click',open);$('boardExit').addEventListener('click',()=>close());
    $('boardPlayBtn').addEventListener('click',()=>{if(!options.getSession())open();});
    return Object.freeze({open,close,move,handleTranscript,isActive:()=>Boolean(game),state:()=>game,roundId:()=>round,context:()=>checkpoint(game)});
  }
  window.MiniBoard=Object.freeze({create,result,place,chooseMove,miniMove,wantsGame,wantsExit,parsePosition,checkpoint,init});
})();
